From 7f8ba0ed0f3344283f29fd6d570892dc6f919801 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Tue, 24 Nov 2026 19:33:48 +0100
Subject: [PATCH] kcms: don't autoconnect imported WireGuard connections

WireGuard connections created in the editor already have autoconnect
off, but importing a .conf file through libnm kept NetworkManager's
default, so the tunnel came up on every boot. Turn it off on import too.

BUG: 493497
---
 kcms/kcm_connections/kcm.cpp     | 1 +
 kcms/kcm_connections_qml/kcm.cpp | 1 +
 2 files changed, 2 insertions(+)

diff --git a/kcms/kcm_connections/kcm.cpp b/kcms/kcm_connections/kcm.cpp
index 3a02834f4..0f17acaad 100644
--- a/kcms/kcm_connections/kcm.cpp
+++ b/kcms/kcm_connections/kcm.cpp
@@ -632,6 +632,7 @@ KCMNetworkmanagement::ImportResult KCMNetworkmanagement::importVpnFile(const QSt
         if (error) {
             qCDebug(PLASMA_NM_KCM_LOG) << "Could not import WireGuard connection" << error->message;
         } else {
+            g_object_set(nm_connection_get_setting_connection(conn), NM_SETTING_CONNECTION_AUTOCONNECT, FALSE, nullptr);
             m_handler->addConnection(conn);
             return ImportResult::pass();
         }
diff --git a/kcms/kcm_connections_qml/kcm.cpp b/kcms/kcm_connections_qml/kcm.cpp
index efe5e0c83..9815d14d2 100644
--- a/kcms/kcm_connections_qml/kcm.cpp
+++ b/kcms/kcm_connections_qml/kcm.cpp
@@ -1336,6 +1336,7 @@ KCMNetworkManagementQml::ImportResult KCMNetworkManagementQml::importVpnFile(con
         NMConnection *conn = nm_conn_wireguard_import(filename.toUtf8().constData(), &error);

         if (conn) {
+            g_object_set(nm_connection_get_setting_connection(conn), NM_SETTING_CONNECTION_AUTOCONNECT, FALSE, nullptr);
             m_handler->addConnection(conn);
             return ImportResult::pass();
         }
